package com.doubleclickdepositworn;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PluginLauncher
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(DoubleDepositPlugin.class);
		RuneLite.main(args);
	}
}

package com.doubleclickdepositworn;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

import java.awt.Color;

@ConfigGroup("doubledeposit")
public interface DoubleDepositConfig extends Config
{
    @ConfigItem(
            keyName = "cooldownMillis",
            name = "Double-click timeout (ms)",
            description = "Time allowed between clicks to confirm deposit"
    )
    default int cooldownMillis()
    {
        return 500;
    }

    @ConfigItem(
            keyName = "overlayOpacity",
            name = "Overlay opacity (0-255)",
            description = "Opacity of the circular overlay (0-255)"
    )
    default int overlayOpacity()
    {
        return 150;
    }

    @ConfigItem(
            keyName = "progressBarColor",
            name = "Progress Bar Color",
            description = "Color of the double-click progress bar"
    )
    default Color progressBarColor()
    {
        return Color.GREEN;
    }
}

package com.doubleclickdepositworn;

import javax.inject.Inject;

import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import java.awt.*;

public class DoubleDepositOverlay extends Overlay
{
    private final Client client;
    private final DoubleDepositPlugin plugin;

    @Inject
    public DoubleDepositOverlay(Client client, DoubleDepositPlugin plugin)
    {
        this.client = client;
        this.plugin = plugin;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(1000.0F);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!plugin.isOverlayVisible())
        {
            return null;
        }

        Widget widget = plugin.getLastDepositWornWidget();
        if (widget == null)
        {
            return null;
        }

        Rectangle bounds = widget.getBounds();
        if (bounds == null)
        {
            return null;
        }

        int centerX = bounds.x + bounds.width / 2;

        int centerY = bounds.y + bounds.height / 2;

        int size = (int) (Math.min(bounds.width, bounds.height) * 0.9);

        graphics.setColor(new Color(0, 0, 0, 50));
        graphics.fillOval(centerX - size / 2, centerY - size / 2, size, size);

        Color c = plugin.getConfig().progressBarColor();
        int alpha = plugin.getOverlayOpacity();

        graphics.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha));

        double progress = plugin.getProgress();
        int arc = -(int) (360 * progress);

        graphics.fillArc(
                centerX - size / 2,
                centerY - size / 2,
                size,
                size,
                90,
                arc
        );

        return null;
    }
}

package com.doubleclickdepositworn;

import javax.inject.Inject;

import com.google.inject.Provides;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
        name = "Double-Click Deposit Worn Items",
        description = "Requires double-click to deposit worn items in the bank within the timed visual overlay",
        tags = {"bank", "safety", "deposit", "qol"}
)
public class DoubleDepositPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Getter
    @Inject
    private DoubleDepositConfig config;

    private DoubleDepositOverlay overlay;

    private long lastClickTime = 0;
    private long overlayStartTime = 0;

    private Widget lastDepositWornWidget;

    @Provides
    DoubleDepositConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(DoubleDepositConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlay = new DoubleDepositOverlay(client, this);
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        overlay = null;

        lastClickTime = 0;
        overlayStartTime = 0;
        lastDepositWornWidget = null;
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (!"Deposit worn items".equals(event.getMenuOption()))
        {
            return;
        }

        if (event.getMenuAction() != MenuAction.CC_OP)
        {
            return;
        }

        Widget w = event.getWidget();
        if (w != null)
        {
            lastDepositWornWidget = w;
        }

        long now = System.currentTimeMillis();

        if (now - lastClickTime > config.cooldownMillis())
        {
            event.consume();
            lastClickTime = now;
            overlayStartTime = now;
            return;
        }

        lastClickTime = 0;
        overlayStartTime = 0;
    }

    public boolean isOverlayVisible()
    {
        return overlayStartTime > 0 &&
                System.currentTimeMillis() - overlayStartTime <= config.cooldownMillis();
    }

    public double getProgress()
    {
        if (!isOverlayVisible())
        {
            return 0.0;
        }

        long elapsed = System.currentTimeMillis() - overlayStartTime;
        return Math.min(1.0, (double) elapsed / config.cooldownMillis());
    }

    public int getOverlayOpacity()
    {
        return config.overlayOpacity();
    }

    public Widget getLastDepositWornWidget()
    {
        return lastDepositWornWidget;
    }
}
